adj = {1:[2,4], 2:[3,5], 3:[1], 4:[5,6], 5:[3,7], 6:[7], 7:[], 8:[6,7]}
t = 0; d = {}; f = {}
def dfs(u):
    global t
    t += 1; d[u] = t
    for v in adj[u]:
        if v not in d: dfs(v)
    t += 1; f[u] = t
for u in sorted(adj):
    if u not in d: dfs(u)
